architecture rtl of compose4_top is
  signal core_clk_i : std_logic;
  signal hbm_aclk_i : std_logic;
begin

  gbufg : if CLK_BUFG generate
    u_bufg_core : BUFGCE port map(I => core_clk, CE => '1', O => core_clk_i);
    u_bufg_hbm  : BUFGCE port map(I => hbm_aclk, CE => '1', O => hbm_aclk_i);
  end generate;
  gnobufg : if not CLK_BUFG generate
    core_clk_i <= core_clk;
    hbm_aclk_i <= hbm_aclk;
  end generate;

  -- a_eng : fk33_engine  (all generics at their file defaults)
  a_eng : entity work.fk33_engine
    port map(
      core_clk => core_clk_i,
      core_aresetn => core_aresetn,
      hbm_aclk => hbm_aclk_i,
      compute_halt => a_eng_compute_halt,
      s_axi_awvalid => a_eng_s_axi_awvalid,
      s_axi_awready => a_eng_s_axi_awready,
      s_axi_awaddr => a_eng_s_axi_awaddr,
      s_axi_awprot => a_eng_s_axi_awprot,
      s_axi_wvalid => a_eng_s_axi_wvalid,
      s_axi_wready => a_eng_s_axi_wready,
      s_axi_wdata => a_eng_s_axi_wdata,
      s_axi_wstrb => a_eng_s_axi_wstrb,
      s_axi_bvalid => a_eng_s_axi_bvalid,
      s_axi_bready => a_eng_s_axi_bready,
      s_axi_bresp => a_eng_s_axi_bresp,
      s_axi_arvalid => a_eng_s_axi_arvalid,
      s_axi_arready => a_eng_s_axi_arready,
      s_axi_araddr => a_eng_s_axi_araddr,
      s_axi_arprot => a_eng_s_axi_arprot,
      s_axi_rvalid => a_eng_s_axi_rvalid,
      s_axi_rready => a_eng_s_axi_rready,
      s_axi_rdata => a_eng_s_axi_rdata,
      s_axi_rresp => a_eng_s_axi_rresp,
      s_axix_awvalid => a_eng_s_axix_awvalid,
      s_axix_awready => a_eng_s_axix_awready,
      s_axix_awaddr => a_eng_s_axix_awaddr,
      s_axix_awprot => a_eng_s_axix_awprot,
      s_axix_wvalid => a_eng_s_axix_wvalid,
      s_axix_wready => a_eng_s_axix_wready,
      s_axix_wdata => a_eng_s_axix_wdata,
      s_axix_wstrb => a_eng_s_axix_wstrb,
      s_axix_bvalid => a_eng_s_axix_bvalid,
